var Au={ctx:null,mg:null,sg:null};
Au.gc=function(){if(!Au.ctx){Au.ctx=new(window.AudioContext||window.webkitAudioContext)();Au.mg=Au.ctx.createGain();Au.mg.connect(Au.ctx.destination);Au.sg=Au.ctx.createGain();Au.sg.connect(Au.mg)}if(Au.ctx.state==="suspended")Au.ctx.resume();return Au.ctx};
Au.t=function(f,d,t,g){var c=Au.gc(),o=c.createOscillator(),gn=c.createGain();o.type=t||"sine";o.frequency.setValueAtTime(f,c.currentTime);gn.gain.setValueAtTime(g||0.2,c.currentTime);gn.gain.exponentialRampToValueAtTime(0.001,c.currentTime+d);o.connect(gn);gn.connect(Au.sg);o.start(c.currentTime);o.stop(c.currentTime+d)};
Au.click=function(){Au.t(800,0.08,"sine",0.2)};Au.ok=function(){var c=Au.gc(),n=c.currentTime;[523,659,784,1047].forEach(function(f,i){var o=c.createOscillator(),g=c.createGain();o.type="sine";o.frequency.setValueAtTime(f,n+i*0.12);g.gain.setValueAtTime(0.2,n+i*0.12);g.gain.exponentialRampToValueAtTime(0.001,n+i*0.12+0.35);o.connect(g);g.connect(Au.sg);o.start(n+i*0.12);o.stop(n+i*0.12+0.4)})};
