Au.coin=function(){Au.t(1200,0.1);setTimeout(function(){Au.t(1600,0.1)},60)};Au.ach=function(){var c=Au.gc(),n=c.currentTime;[523,659,784,1047,1319].forEach(function(f,i){var o=c.createOscillator(),g=c.createGain();o.type="triangle";o.frequency.setValueAtTime(f,n+i*0.1);g.gain.setValueAtTime(0.2,n+i*0.1);g.gain.exponentialRampToValueAtTime(0.001,n+i*0.1+0.4);o.connect(g);g.connect(Au.sg);o.start(n+i*0.1);o.stop(n+i*0.1+0.45)})};

