var Pt={c:null,x:null,p:[],t:[],r:false};
Pt.init=function(){Pt.c=$("particles-canvas");Pt.x=Pt.c.getContext("2d");Pt.c.width=window.innerWidth;Pt.c.height=window.innerHeight;window.addEventListener("resize",function(){Pt.c.width=window.innerWidth;Pt.c.height=window.innerHeight});Pt.r=true;Pt.loop()};
