Pt.ft=function(x,y,tx,c,s){Pt.t.push({x:x,y:y,tx:tx,c:c||"#FFD700",s:s||20,vy:-1.5,l:1.5,ml:1.5})};Pt.light=function(x,y){for(var i=0;i<15;i++)Pt.p.push({x:x+(Math.random()-0.5)*60,y:y,vx:(Math.random()-0.5)*2,vy:-3-Math.random()*5,l:0.3+Math.random()*0.4,ml:0.7,s:1+Math.random()*2,c:"#FFD700"})};

