function mEd(){if(eb_.length<2)return;var is=eb_.map(function(id){return EAGLE_I.find(function(i){return i.id===id})}).filter(Boolean);var en=0,ta=0,sw=0,rf=0,co=0,po=0;is.forEach(function(i){en+=i.en;ta+=i.ta;sw+=i.sw;rf+=i.rf;co+=i.co;po+=i.po});var n=is.length;en=Math.min(100,Math.round(en/n));ta=Math.min(100,Math.round(ta/n));sw=Math.min(100,Math.round(sw/n));rf=Math.min(100,Math.round(rf/n));co=Math.round(co);po=Math.min(100,Math.round(po/n));var mb=0;if(em_){var mc=0,tt=0;Object.keys(em_.tg).forEach(function(k){tt++;var v=k==="co"?co:({en:en,ta:ta,sw:sw,rf:rf,po:po}[k]||0);if(k==="co"?v<=em_.tg[k]:v>=em_.tg[k])mc++});mb=Math.round(mc/tt*em_.rw)}var pk=GS.ea.pk,pb=(pk.c==="gold"?10:0)+(pk.l==="eagle"?10:0)+(pk.p==="lightning"?10:0)+(pk.f==="glossy"?5:0);var tb=mb+pb;GS.ea.pop=Math.min(100,GS.ea.pop+Math.round(po/10));GS.ea.tr=Math.min(100,GS.ea.tr+Math.round(ta/20));GS.ea.ms=Math.min(100,GS.ea.ms+Math.round(po/15));GS.ea.rv+=tb+co*10;GS.ea.dr.push({is:is.map(function(i){return i.n}),en:en,ta:ta,sw:sw,rf:rf,co:co,po:po,bn:tb});if(GS.ea.rv>=200&&GS.ea.um.indexOf("albania")===-1)GS.ea.um.push("albania");if(GS.ea.rv>=500&&GS.ea.um.indexOf("germany")===-1)GS.ea.um.push("germany");if(GS.ea.rv>=1000&&GS.ea.um.indexOf("italy")===-1)GS.ea.um.push("italy");if(GS.ea.rv>=2000&&GS.ea.um.indexOf("uk")===-1)GS.ea.um.push("uk");if(GS.ea.rv>=3000&&GS.ea.um.indexOf("switzerland")===-1)GS.ea.um.push("switzerland");if(GS.ea.rv>=5000&&GS.ea.um.indexOf("usa")===-1)GS.ea.um.push("usa");ac(tb);sv(GS);var rs=$("eg-rs");rs.style.display="block";rs.innerHTML='<h3 style="color:var(--eagle-gold)">⚡ Energy Drink Created!</h3><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0"><div><strong>Energy</strong><br>'+en+'/100<div class="progress-bar"><div class="progress-fill" style="width:'+en+'%;background:var(--eagle-neon)"></div></div></div><div><strong>Taste</strong><br>'+ta+'/100<div class="progress-bar"><div class="progress-fill" style="width:'+ta+'%"></div></div></div><div><strong>Sweetness</strong><br>'+sw+'/100<div class="progress-bar"><div class="progress-fill" style="width:'+sw+'%;background:#FF69B4"></div></div></div><div><strong>Refresh</strong><br>'+rf+'/100<div class="progress-bar"><div class="progress-fill" style="width:'+rf+'%;background:#00BFFF"></div></div></div><div><strong>Cost</strong><br>'+co+'€</div><div><strong>Popularity</strong><br>'+po+'/100<div class="progress-bar"><div class="progress-fill" style="width:'+po+'%;background:#FFD700"></div></div></div></div><div style="text-align:center;font-size:1.2rem"><strong>Mission Bonus:</strong> +'+mb+' 🪙 | <strong>Packaging:</strong> +'+pb+" 🪙</div><div style=\"text-align:center;font-size:1.3rem;color:var(--eagle-gold);margin-top:8px\"><strong>Total Earned:</strong> +"+tb+' 🪙</div><button class="eagle-btn" style="margin-top:12px" onclick="rEf()">🔄 New Mission</button>';Pt.light(window.innerWidth/2,window.innerHeight/2);Au.ach();em_=EAGLE_MS[Math.floor(Math.random()*EAGLE_MS.length)];eb_=[];setTimeout(function(){rEagle()},3000)}
function rEf(){em_=EAGLE_MS[Math.floor(Math.random()*EAGLE_MS.length)];rEagle()}

